      "每3回合召唤幼狼；每4回合发动狼王咆哮。": "3ターンごとに子狼を召喚し、4ターンごとに狼王の咆哮を放つ。",
      "狼王号令": "狼王の号令",
      "每3个敌方回合，在空位免费召唤1只幼狼。": "敵のターン3回ごとに、空いている位置に子狼を1体無償で召喚する。",
      "裂月咆哮": "裂月の咆哮",
      "每4个敌方回合，使所有狼类随从永久获得+1攻击。": "敵のターン4回ごとに、狼族のミニオン全ては永続的に攻撃力+1を得る。",
      "银灰狼女猎手": "銀灰の狼女狩人",
      "千枝城的灰牙首领": "千枝城の灰牙の首領",
      "避开翡翠城追兵、占据千枝城废墟的狼族首领。每回合都会呼唤一只迅猛的灰狼投入战斗。": "翡翠城の追っ手を逃れ、千枝城の廃墟を占拠した狼族の首領。毎ターン俊敏な灰狼を1体戦場に呼び込む。",
      "灰狼增援": "灰狼の増援",
      "每个敌方行动回合，召唤1只4攻/1血、可立即攻击随从的突击灰狼。": "敵の行動ターンごとに、ミニオンをすぐ攻撃できる4/1の突撃灰狼を1体召喚する。",
      "千枝城魔族军官团": "千枝城魔族士官団",
      "拒绝退避的重建者": "退かぬ再建者たち",
      "第五关剧情结束后驻扎于千枝城的魔族据点。随从均为20攻/200血，属于长期挑战内容。": "第5章のストーリー後に千枝城に駐留する魔族の拠点。ミニオンは全て20/200で、長期的なやり込みコンテンツ。",
