      "梦幻森林二十史莱姆首领路线图": "夢幻の森・スライムのボス20体のルートマップ",
      "金麦农场二十首领路线图": "金麦農場・ボス20体のルートマップ",
      "哥布林王庭二十节点路线图": "ゴブリン王宮・20ノードのルートマップ",
      "迷雾森林十三节点路线图": "霧の森・13ノードのルートマップ",
      "千枝城古城废墟": "千枝城古都廃墟",
