      "罗兰·维克": "ローランド・ヴィック",
      "前王都护卫队长": "元王都護衛隊長",
      "莉瑟尔": "リゼル",
      "薇奥菈": "ヴィオラ",
      "赛琳娜": "セリーナ",
      "格罗姆": "グロム",
      "埃尔德": "エルド",
      "奥斯坦": "オスタン",
      "希尔瓦": "シルヴァ",
      "翠羽射手": "翠羽の射手",
      "紫晶魔女": "紫晶の魔女",
      "晨曦圣女": "暁の聖女",
      "裂角蛮王": "裂角の蛮王",
      "银叶游侠": "銀葉の遊侠",
      "银盾骑士": "銀盾の騎士",
      "森灵德鲁伊": "森霊のドルイド",
      "林海边境最年轻的神射手，她的箭能穿过层层枝叶，找到藏在阵后的敌人。": "森の辺境で最も若い名射手。彼女の矢は幾重もの枝葉をすり抜け、陣の後ろに隠れた敵を捉える。",
      "离开法塔独自研究裂隙的魔女，擅长把魔力拆成无数枚难以躲避的飞弹。": "魔法塔を離れ、独りで裂け目を研究する魔女。魔力を無数の避けがたい飛弾に分けるのが得意。",
      "太阳神殿派往前线的圣女，相信每一名士兵都值得再站起来一次。": "太陽神殿から前線へ遣わされた聖女。すべての兵士にもう一度立ち上がる価値があると信じている。",
      "北地部族的蛮王，以自己的鲜血点燃战士的怒火。": "北方部族の蛮王。自らの血で戦士たちの怒りに火をつける。",
      "月林巡林员的首领，总能让敌人在树影里看到不该出现的弓手。": "月林の巡林隊の長。敵はいつも、いるはずのない弓手を木陰に見ることになる。",
      "王都晨辉骑士团的老兵，他的盾阵从未在他面前后退一步。": "王都暁光騎士団の古参兵。彼の盾陣は一歩も退いたことがない。",
      "古林之心孕育的德鲁伊，她种下的每一株幼苗都会长成守护森林的古树。": "古き森の心臓から生まれたドルイド。彼女が植えた苗はすべて森を守る古木へと育つ。",
